static void view_zoom_to_window_xy_3d(.text:
static void view_zoom_to_window_xy_3d(ARegion *region, float dfac, const int zoom_xy[2])
{
  RegionView3D *rv3d = static_cast<RegionView3D *>(region->regiondata);
  const float dist_new = rv3d->dist * dfac;

  if (zoom_xy != nullptr) {
    float dvec[3];
    float tvec[3];
    float tpos[3];
    float xy_delta[2];

    float zfac;

    negate_v3_v3(tpos, rv3d->ofs);

    xy_delta[0] = float(((zoom_xy[0] - region->winrct.xmin) * 2) - region->winx) / 2.0f;
    xy_delta[1] = float(((zoom_xy[1] - region->winrct.ymin) * 2) - region->winy) / 2.0f;

    /* Project cursor position into 3D space */
    zfac = ED_view3d_calc_zfac(rv3d, tpos);
    ED_view3d_win_to_delta(region, xy_delta, zfac, dvec);

    /* Calculate view target position for dolly */
    add_v3_v3v3(tvec, tpos, dvec);
    negate_v3(tvec);

    /* Offset to target position and dolly */
    copy_v3_v3(rv3d->ofs, tvec);
    rv3d->dist = dist_new;

    /* Calculate final offset */
    madd_v3_v3v3fl(rv3d->ofs, tvec, dvec, dfac);
  }
  else {
    rv3d->dist = dist_new;
  }
}

static float viewzoom_scale_value(.text:
static float viewzoom_scale_value(const rcti *winrct,
                                  const eViewZoom_Style viewzoom,
                                  const bool zoom_invert,
                                  const bool zoom_invert_force,
                                  const int xy_curr[2],
                                  const int xy_init[2],
                                  const float val,
                                  const float val_orig,
                                  double *r_timer_lastdraw)
{
  float zfac;

  if (viewzoom == USER_ZOOM_CONTINUE) {
    double time = BLI_time_now_seconds();
    float time_step = float(time - *r_timer_lastdraw);
    float fac;

    if (U.uiflag & USER_ZOOM_HORIZ) {
      fac = float(xy_init[0] - xy_curr[0]);
    }
    else {
      fac = float(xy_init[1] - xy_curr[1]);
    }

    fac /= UI_SCALE_FAC;

    if (zoom_invert != zoom_invert_force) {
      fac = -fac;
    }

    zfac = 1.0f + ((fac / 20.0f) * time_step);
    *r_timer_lastdraw = time;
  }
  else if (viewzoom == USER_ZOOM_SCALE) {
    /* method which zooms based on how far you move the mouse */

    const int ctr[2] = {
        BLI_rcti_cent_x(winrct),
        BLI_rcti_cent_y(winrct),
    };
    float len_new = (5 * UI_SCALE_FAC) + (len_v2v2_int(ctr, xy_curr) / UI_SCALE_FAC);
    float len_old = (5 * UI_SCALE_FAC) + (len_v2v2_int(ctr, xy_init) / UI_SCALE_FAC);

    /* intentionally ignore 'zoom_invert' for scale */
    if (zoom_invert_force) {
      std::swap(len_new, len_old);
    }

    zfac = val_orig * (len_old / max_ff(len_new, 1.0f)) / val;
  }
  else { /* USER_ZOOM_DOLLY */
    float len_new = 5 * UI_SCALE_FAC;
    float len_old = 5 * UI_SCALE_FAC;

    if (U.uiflag & USER_ZOOM_HORIZ) {
      len_new += (winrct->xmax - (xy_curr[0])) / UI_SCALE_FAC;
      len_old += (winrct->xmax - (xy_init[0])) / UI_SCALE_FAC;
    }
    else {
      len_new += (winrct->ymax - (xy_curr[1])) / UI_SCALE_FAC;
      len_old += (winrct->ymax - (xy_init[1])) / UI_SCALE_FAC;
    }

    if (zoom_invert != zoom_invert_force) {
      std::swap(len_new, len_old);
    }

    zfac = val_orig * (2.0f * ((len_new / max_ff(len_old, 1.0f)) - 1.0f) + 1.0f) / val;
  }

  return zfac;
}

static float viewzoom_scale_value_offset.text:
static float viewzoom_scale_value_offset(const rcti *winrct,
                                         const eViewZoom_Style viewzoom,
                                         const bool zoom_invert,
                                         const bool zoom_invert_force,
                                         const int xy_curr[2],
                                         const int xy_init[2],
                                         const int xy_offset[2],
                                         const float val,
                                         const float val_orig,
                                         double *r_timer_lastdraw)
{
  const int xy_curr_offset[2] = {
      xy_curr[0] + xy_offset[0],
      xy_curr[1] + xy_offset[1],
  };
  const int xy_init_offset[2] = {
      xy_init[0] + xy_offset[0],
      xy_init[1] + xy_offset[1],
  };
  return viewzoom_scale_value(winrct,
                              viewzoom,
                              zoom_invert,
                              zoom_invert_force,
                              xy_curr_offset,
                              xy_init_offset,
                              val,
                              val_orig,
                              r_timer_lastdraw);
}

static void viewzoom_apply_3d(.text:
static void viewzoom_apply_3d(ViewOpsData *vod,
                              const int xy[2],
                              const eViewZoom_Style viewzoom,
                              const bool zoom_invert,
                              const bool zoom_to_pos)
{
  const blender::Bounds<float> dist_range = ED_view3d_dist_soft_range_get(vod->v3d, false);
  float zfac = viewzoom_scale_value_offset(&vod->region->winrct,
                                           viewzoom,
                                           zoom_invert,
                                           false,
                                           xy,
                                           vod->init.event_xy,
                                           vod->init.event_xy_offset,
                                           vod->rv3d->dist,
                                           vod->init.dist,
                                           &vod->prev.time);

  if (zfac != 1.0f) {
    const float zfac_min = dist_range.min / vod->rv3d->dist;
    const float zfac_max = dist_range.max / vod->rv3d->dist;
    CLAMP(zfac, zfac_min, zfac_max);

    view_zoom_to_window_xy_3d(vod->region, zfac, zoom_to_pos ? vod->prev.event_xy : nullptr);
  }

  /* these limits were in old code too */
  CLAMP(vod->rv3d->dist, dist_range.min, dist_range.max);

  if (RV3D_LOCK_FLAGS(vod->rv3d) & RV3D_BOXVIEW) {
    view3d_boxview_sync(vod->area, vod->region);
  }

  ED_view3d_camera_lock_sync(vod->depsgraph, vod->v3d, vod->rv3d);

  ED_region_tag_redraw(vod->region);
}

static void viewzoom_apply(.text:
static void viewzoom_apply(ViewOpsData *vod,
                           const int xy[2],
                           const eViewZoom_Style viewzoom,
                           const bool zoom_invert)
{
  const bool zoom_to_pos = (vod->viewops_flag & VIEWOPS_FLAG_ZOOM_TO_MOUSE) != 0;

  if ((vod->rv3d->persp == RV3D_CAMOB) &&
      (vod->rv3d->is_persp && ED_view3d_camera_lock_check(vod->v3d, vod->rv3d)) == 0)
  {
    viewzoom_apply_camera(vod, xy, viewzoom, zoom_invert, zoom_to_pos);
  }
  else {
    viewzoom_apply_3d(vod, xy, viewzoom, zoom_invert, zoom_to_pos);
  }
}

static wmOperatorStatus viewzoom_invoke_.text:
static wmOperatorStatus viewzoom_invoke_impl(bContext *C,
                                             ViewOpsData *vod,
                                             const wmEvent *event,
                                             PointerRNA *ptr)
{
  int xy[2];

  PropertyRNA *prop;
  prop = RNA_struct_find_property(ptr, "mx");
  xy[0] = RNA_property_is_set(ptr, prop) ? RNA_property_int_get(ptr, prop) : event->xy[0];

  prop = RNA_struct_find_property(ptr, "my");
  xy[1] = RNA_property_is_set(ptr, prop) ? RNA_property_int_get(ptr, prop) : event->xy[1];

  prop = RNA_struct_find_property(ptr, "delta");
  const int delta = RNA_property_is_set(ptr, prop) ? RNA_property_int_get(ptr, prop) : 0;

  if (delta) {
    const bool do_zoom_to_mouse_pos = (vod->viewops_flag & VIEWOPS_FLAG_ZOOM_TO_MOUSE) != 0;
    view_zoom_apply_step(C,
                         vod->depsgraph,
                         vod->scene,
                         vod->area,
                         vod->region,
                         delta,
                         do_zoom_to_mouse_pos ? xy : nullptr);

    return OPERATOR_FINISHED;
  }

  eV3D_OpEvent event_code = ELEM(event->type, MOUSEZOOM, MOUSEPAN) ? VIEW_CONFIRM : VIEW_PASS;
  if (event_code == VIEW_CONFIRM) {
    if (U.uiflag & USER_ZOOM_HORIZ) {
      vod->init.event_xy[0] = vod->prev.event_xy[0] = xy[0];
    }
    else {
      /* Set y move = x move as MOUSEZOOM uses only x axis to pass magnification value */
      vod->init.event_xy[1] = vod->prev.event_xy[1] = vod->init.event_xy[1] + xy[0] -
                                                      event->prev_xy[0];
    }
    viewzoom_apply(vod, event->prev_xy, USER_ZOOM_DOLLY, (U.uiflag & USER_ZOOM_INVERT) != 0);
    ED_view3d_camera_lock_autokey(vod->v3d, vod->rv3d, C, false, true);

    return OPERATOR_FINISHED;
  }

  if (U.viewzoom == USER_ZOOM_CONTINUE) {
    /* needs a timer to continue redrawing */
    vod->timer = WM_event_timer_add(CTX_wm_manager(C), CTX_wm_window(C), TIMER, 0.01f);
    vod->prev.time = BLI_time_now_seconds();
  }

  return OPERATOR_RUNNING_MODAL;
}

static wmOperatorStatus view3d_navigatio.text:
static wmOperatorStatus view3d_navigation_invoke_generic(bContext *C,
                                                         ViewOpsData *vod,
                                                         const wmEvent *event,
                                                         PointerRNA *ptr,
                                                         const ViewOpsType *nav_type,
                                                         const float dyn_ofs_override[3])
{
  if (!nav_type->init_fn) {
    return OPERATOR_CANCELLED;
  }

  bool use_cursor_init = false;
  if (PropertyRNA *prop = RNA_struct_find_property(ptr, "use_cursor_init")) {
    use_cursor_init = RNA_property_boolean_get(ptr, prop);
  }

  vod->init_navigation(C, event, nav_type, dyn_ofs_override, use_cursor_init);
  ED_view3d_smooth_view_force_finish(C, vod->v3d, vod->region);

  return nav_type->init_fn(C, vod, event, ptr);
}

wmOperatorStatus view3d_navigate_invoke_.text:
wmOperatorStatus view3d_navigate_invoke_impl(bContext *C,
                                             wmOperator *op,
                                             const wmEvent *event,
                                             const ViewOpsType *nav_type)
{
  ViewOpsData *vod = new ViewOpsData();
  vod->init_context(C);
  wmOperatorStatus ret = view3d_navigation_invoke_generic(
      C, vod, event, op->ptr, nav_type, nullptr);
  op->customdata = (void *)vod;

  if (ret == OPERATOR_RUNNING_MODAL) {
    WM_event_add_modal_handler(C, op);
    return OPERATOR_RUNNING_MODAL;
  }

  viewops_data_free(C, vod);
  op->customdata = nullptr;
  return ret;
}

static wmOperatorStatus viewzoom_invoke(.text:
static wmOperatorStatus viewzoom_invoke(bContext *C, wmOperator *op, const wmEvent *event)
{
  /* Near duplicate logic in #viewdolly_invoke(), changes here may apply there too. */
  return view3d_navigate_invoke_impl(C, op, event, &ViewOpsType_zoom);
}

static wmOperatorStatus viewzoom_exec(.text:
static wmOperatorStatus viewzoom_exec(bContext *C, wmOperator *op)
{
  BLI_assert(op->customdata == nullptr);

  Depsgraph *depsgraph = CTX_data_ensure_evaluated_depsgraph(C);
  Scene *scene = CTX_data_scene(C);
  ScrArea *area = CTX_wm_area(C);
  ARegion *region = CTX_wm_region(C);
  View3D *v3d = static_cast<View3D *>(area->spacedata.first);
  RegionView3D *rv3d = static_cast<RegionView3D *>(region->regiondata);

  const int delta = RNA_int_get(op->ptr, "delta");
  const bool use_cursor_init = RNA_boolean_get(op->ptr, "use_cursor_init");

  int zoom_xy_buf[2];
  const int *zoom_xy = nullptr;
  const bool do_zoom_to_mouse_pos = (use_cursor_init && (U.uiflag & USER_ZOOM_TO_MOUSEPOS));
  if (do_zoom_to_mouse_pos) {
    zoom_xy_buf[0] = RNA_struct_property_is_set(op->ptr, "mx") ? RNA_int_get(op->ptr, "mx") :
                                                                 region->winx / 2;
    zoom_xy_buf[1] = RNA_struct_property_is_set(op->ptr, "my") ? RNA_int_get(op->ptr, "my") :
                                                                 region->winy / 2;
    zoom_xy = zoom_xy_buf;
  }

  view_zoom_apply_step(C, depsgraph, scene, area, region, delta, zoom_xy);
  ED_view3d_camera_lock_undo_grouped_push(op->type->name, v3d, rv3d, C);

  return OPERATOR_FINISHED;
}

bool ED_view3d_native_zoom_type_is(.text:
bool ED_view3d_native_zoom_type_is(const wmOperatorType *ot)
{
  if (ot == nullptr || ot->flag != (OPTYPE_BLOCKING | OPTYPE_GRAB_CURSOR_XY) ||
      ot->pyop_poll != nullptr || ot->macro.first != nullptr || ot->macro.last != nullptr ||
      ot->rna_ext.data != nullptr || ot->rna_ext.srna != nullptr || ot->rna_ext.call != nullptr ||
      ot->rna_ext.free != nullptr)
  {
    return false;
  }

  return ot->poll == view3d_zoom_or_dolly_poll && ot->exec == viewzoom_exec &&
         ot->invoke == viewzoom_invoke && ot->modal == view3d_navigate_modal_fn &&
         ot->cancel == view3d_navigate_cancel_fn;
}

static wmOperatorStatus viewmove_invoke_.text:
static wmOperatorStatus viewmove_invoke_impl(bContext *C,
                                             ViewOpsData *vod,
                                             const wmEvent *event,
                                             PointerRNA * /*ptr*/)
{
  eV3D_OpEvent event_code = event->type == MOUSEPAN ? VIEW_CONFIRM : VIEW_PASS;

  if (event_code == VIEW_CONFIRM) {
    /* Invert it, trackpad scroll follows same principle as 2d windows this way. */
    int mx = 2 * event->xy[0] - event->prev_xy[0];
    int my = 2 * event->xy[1] - event->prev_xy[1];
    viewmove_apply(vod, mx, my);

    ED_view3d_camera_lock_autokey(vod->v3d, vod->rv3d, C, false, true);
    return OPERATOR_FINISHED;
  }

  return OPERATOR_RUNNING_MODAL;
}

static wmOperatorStatus viewrotate_invok.text:
static wmOperatorStatus viewrotate_invoke_impl(bContext *C,
                                               ViewOpsData *vod,
                                               const wmEvent *event,
                                               PointerRNA * /*ptr*/)
{
  if (vod->use_dyn_ofs && (vod->rv3d->is_persp == false)) {
    vod->use_dyn_ofs_ortho_correction = true;
  }

  eV3D_OpEvent event_code = ELEM(event->type, MOUSEROTATE, MOUSEPAN) ? VIEW_CONFIRM : VIEW_PASS;

  if (event_code == VIEW_CONFIRM) {
    /* MOUSEROTATE performs orbital rotation, so y axis delta is set to 0 */
    const bool is_inverted = (event->flag & WM_EVENT_SCROLL_INVERT) &&
                             (event->type != MOUSEROTATE);

    int m_xy[2];
    if (is_inverted) {
      m_xy[0] = 2 * event->xy[0] - event->prev_xy[0];
      m_xy[1] = 2 * event->xy[1] - event->prev_xy[1];
    }
    else {
      copy_v2_v2_int(m_xy, event->prev_xy);
    }
    viewrotate_apply(vod, m_xy);

    ED_view3d_camera_lock_autokey(vod->v3d, vod->rv3d, C, true, true);
    return OPERATOR_FINISHED;
  }

  return OPERATOR_RUNNING_MODAL;
}

static wmOperatorStatus viewmove_invoke(.text:
static wmOperatorStatus viewmove_invoke(bContext *C, wmOperator *op, const wmEvent *event)
{
#ifdef WITH_APPLE_CROSSPLATFORM
  /* Filter finger-pan gestures only. Pencil/native gizmo LEFTMOUSE presses,
   * keyboard invocation and external mouse drags use Blender's modal path. */
  if (event->type == MOUSEPAN &&
      !(event->flag & (WM_EVENT_MULTITOUCH_TWO_FINGERS | WM_EVENT_MULTITOUCH_THREE_FINGERS)))
  {
    return OPERATOR_FINISHED;
  }
#endif

  return view3d_navigate_invoke_impl(C, op, event, &ViewOpsType_move);
}

static wmOperatorStatus viewrotate_invok.text:
static wmOperatorStatus viewrotate_invoke(bContext *C, wmOperator *op, const wmEvent *event)
{
#ifdef WITH_APPLE_CROSSPLATFORM
  /* Filter finger scrolling only; native gizmo and external pointer presses
   * must reach Blender's modal rotation path. */
  if (event->type == MOUSEPAN && !(event->flag & WM_EVENT_MULTITOUCH_TWO_FINGERS)) {
    return OPERATOR_FINISHED;
  }
#endif

  return view3d_navigate_invoke_impl(C, op, event, &ViewOpsType_rotate);
}

static const wmKeyMap *wm_ipad_knife_pan.text:
static const wmKeyMap *wm_ipad_knife_pan_map_find(const wmKeyConfig *config,
                                                const char *name,
                                                const int space,
                                                const int region)
{
  const wmKeyMap *found = nullptr;
  LISTBASE_FOREACH (const wmKeyMap *, map, &config->keymaps) {
    if (wm_ipad_node_view2d_string_is(map->idname, sizeof(map->idname), name) &&
        map->spaceid == space && map->regionid == region)
    {
      if (found) return nullptr;
      found = map;
    }
  }
  return found;
}

static bool wm_ipad_knife_pan_map_header.text:
static bool wm_ipad_knife_pan_map_header_is(const wmKeyMap *map,
                                           const bool effective,
                                           const bool modal)
{
  const int allowed = KEYMAP_EXPANDED | KEYMAP_CHILDREN_EXPANDED |
                      (effective ? KEYMAP_USER : KEYMAP_UPDATE) | (modal ? KEYMAP_MODAL : 0);
  return map && map->owner_id[0] == '\0' && !map->poll && !map->poll_modal_item &&
         !map->diff_items.first && !map->diff_items.last && map->kmi_id > 0 &&
         (map->flag & ~allowed) == 0 &&
         (map->flag & KEYMAP_USER) == (effective ? KEYMAP_USER : 0) &&
         (map->flag & KEYMAP_MODAL) == (modal ? KEYMAP_MODAL : 0) &&
         (modal ? map->modal_items != nullptr : map->modal_items == nullptr);
}

static const wmKeyMapItem *wm_ipad_knife.text:
static const wmKeyMapItem *wm_ipad_knife_pan_zoom_item(const wmKeyMap *map,
                                                     const bool effective)
{
  if (!wm_ipad_knife_pan_map_header_is(map, effective, false)) return nullptr;
  const wmKeyMapItem *found = nullptr, *previous = nullptr;
  LISTBASE_FOREACH (const wmKeyMapItem *, item, &map->items) {
    if (item->prev != previous) return nullptr;
    previous = item;
    if (!wm_ipad_node_view2d_string_is(item->idname, sizeof(item->idname), "VIEW3D_OT_zoom") ||
        item->type != MOUSEPAN)
    {
      continue;
    }
    /* A second PAN zoom profile is ambiguous, even when it does not match now. */
    if (found || item->id <= 0 || item->id > map->kmi_id || item->val != KM_ANY ||
        item->direction != KM_ANY || item->shift != KM_NOTHING || item->ctrl != KM_PRESS ||
        item->alt != KM_NOTHING || item->oskey != KM_NOTHING || item->hyper != KM_NOTHING ||
        item->keymodifier != EVENT_NONE || item->maptype != 0 || item->propvalue != 0 ||
        item->propvalue_str[0] != '\0' ||
        (item->flag & ~(KMI_EXPANDED | (effective ? 0 : KMI_UPDATE))) != KMI_REPEAT_IGNORE)
    {
      return nullptr;
    }
    const IDProperty *properties = item->properties;
    const PointerRNA *ptr = item->ptr;
    const wmOperatorType *type = WM_operatortype_find("VIEW3D_OT_zoom", true);
    if (!type || !type->srna || !ED_view3d_native_zoom_type_is(type) || !properties ||
        properties->type != IDP_GROUP || properties->len != 0 ||
        properties->data.group.first || properties->data.group.last || !ptr ||
        ptr->data != properties || ptr->owner_id || ptr->type != type->srna)
    {
      return nullptr;
    }
    found = item;
  }
  return map->items.last == previous ? found : nullptr;
}

static const wmKeyMapItem *wm_ipad_knife_panning_item(const wmKeyMap *map,
                                                    const bool effective)
{
  if (!wm_ipad_knife_pan_map_header_is(map, effective, true)) return nullptr;
  const wmKeyMapItem *found = nullptr, *previous = nullptr;
  LISTBASE_FOREACH (const wmKeyMapItem *, item, &map->items) {
    if (item->prev != previous) return nullptr;
    previous = item;
    if (item->propvalue != 15) continue; /* Native KNF_MODAL_PANNING. */
    if (found || item->id <= 0 || item->id > map->kmi_id || item->type != MIDDLEMOUSE ||
        item->val != KM_ANY || item->direction != KM_ANY || item->shift != KM_ANY ||
        item->ctrl != KM_ANY || item->alt != KM_ANY || item->oskey != KM_ANY ||
        item->hyper != KM_ANY || item->keymodifier != EVENT_NONE || item->maptype != 0 ||
        item->idname[0] != '\0' || item->propvalue_str[0] != '\0' || item->ptr ||
        item->properties ||
        (item->flag & ~(KMI_EXPANDED | (effective ? 0 : KMI_UPDATE))) != KMI_REPEAT_IGNORE)
    {
      return nullptr;
    }
    found = item;
  }
  return map->items.last == previous ? found : nullptr;
}

static bool wm_ipad_knife_precision_pan_.text:
static bool wm_ipad_knife_precision_pan_owner_context(bContext *C)
{
  if (!C || CTX_py_dict_get(C) != nullptr) return false;
  wmWindow *win = CTX_wm_window(C);
  ScrArea *area = CTX_wm_area(C);
  ARegion *region = CTX_wm_region(C);
  if (!win || !area || area->spacetype != SPACE_VIEW3D || !region ||
      region->regiontype != RGN_TYPE_WINDOW || BLI_findindex(&area->regionbase, region) < 0)
  {
    return false;
  }
  wmIPadKnifeOwner owner;
  if (!WM_ipad_knife_owner_capture(C, win, area, owner) ||
      owner.values[K_REGION] != uint64_t(uintptr_t(region)))
  {
    return false;
  }
  const wmWindowManager *wm = CTX_wm_manager(C);
  if (!wm || !wm->runtime || !wm->runtime->defaultconf || !wm->runtime->userconf ||
      wm->runtime->defaultconf == wm->runtime->userconf ||
      BLI_findindex(&wm->runtime->keyconfigs, wm->runtime->defaultconf) < 0 ||
      BLI_findindex(&wm->runtime->keyconfigs, wm->runtime->userconf) < 0)
  {
    return false;
  }
  const wmKeyMap *base_map = wm_ipad_knife_pan_map_find(
      wm->runtime->defaultconf, "Knife Tool Modal Map", 0, 0);
  const wmKeyMap *effective_map = wm_ipad_knife_pan_map_find(
      wm->runtime->userconf, "Knife Tool Modal Map", 0, 0);
  const wmKeyMapItem *base_item = wm_ipad_knife_panning_item(base_map, false);
  const wmKeyMapItem *effective_item = wm_ipad_knife_panning_item(effective_map, true);
  if (!base_map || !effective_map || base_map->kmi_id != effective_map->kmi_id ||
      base_map->modal_items != effective_map->modal_items || !base_item || !effective_item ||
      base_item->id != effective_item->id)
  {
    return false;
  }
  LISTBASE_FOREACH (wmEventHandler *, base_handler, &win->modalhandlers) {
    if (uint64_t(uintptr_t(base_handler)) != owner.values[K_HANDLER]) continue;
    /* The strict find-only capture above proved this exact live registered
     * handler/operator/type/context. No callback occurs in this native query. */
    const auto *handler = reinterpret_cast<const wmEventHandler_Op *>(base_handler);
    return handler->op && handler->op->type && handler->op->type->modalkeymap == base_map &&
           ED_mesh_knife_modal_navigation_may_be_denied(handler->op);
  }
  return false;
}

static eIPadNativePanDispatch wm_ipad_kn.text:
static eIPadNativePanDispatch wm_ipad_knife_pan_zoom_dispatch(
    bContext *C,
    const wmEvent *event,
    const ListBase *handlers,
    const wmEventHandler_Keymap *handler,
    const wmKeyMap *keymap,
    const wmKeyMapItem *matched)
{
  if (!wm_ipad_knife_precision_pan_event_context(C, event)) {
    return eIPadNativePanDispatch::None;
  }
  const ARegion *region = CTX_wm_region(C);
  const wmWindowManager *wm = CTX_wm_manager(C);
  if (!region || !region->runtime || handlers != &region->runtime->handlers || !handler ||
      BLI_findindex(handlers, &handler->head) < 0 ||
      handler->head.type != WM_HANDLER_TYPE_KEYMAP || handler->head.flag != 0 ||
      handler->head.poll || handler->dynamic.keymap_fn || handler->dynamic.user_data ||
      handler->post.post_fn || handler->post.user_data || handler->keymap_tool ||
      !wm || !wm->runtime || !wm->runtime->defaultconf || !wm->runtime->userconf ||
      wm->runtime->defaultconf == wm->runtime->userconf ||
      BLI_findindex(&wm->runtime->keyconfigs, wm->runtime->defaultconf) < 0 ||
      BLI_findindex(&wm->runtime->keyconfigs, wm->runtime->userconf) < 0)
  {
    return eIPadNativePanDispatch::None;
  }
  const wmKeyConfig *base = wm->runtime->defaultconf;
  const wmKeyConfig *effective = wm->runtime->userconf;
  const wmKeyConfig *active = base;
  LISTBASE_FOREACH (const wmKeyConfig *, config, &wm->runtime->keyconfigs) {
    if (strncmp(config->idname, U.keyconfigstr, sizeof(config->idname)) == 0) {
      active = config;
      break;
    }
  }
  if (active != base) return eIPadNativePanDispatch::None;
  const wmKeyMap *base_map = wm_ipad_knife_pan_map_find(base, "3D View", SPACE_VIEW3D,
                                                      RGN_TYPE_WINDOW);
  const wmKeyMap *effective_map = wm_ipad_knife_pan_map_find(effective, "3D View", SPACE_VIEW3D,
                                                           RGN_TYPE_WINDOW);
  if (!base_map || handler->keymap != base_map || !effective_map || keymap != effective_map ||
      base_map->kmi_id != effective_map->kmi_id)
  {
    return eIPadNativePanDispatch::None;
  }
  const wmKeyMapItem *base_item = wm_ipad_knife_pan_zoom_item(base_map, false);
  const wmKeyMapItem *effective_item = wm_ipad_knife_pan_zoom_item(effective_map, true);
  return base_item && effective_item && matched == effective_item &&
                 base_item->id == effective_item->id ?
             eIPadNativePanDispatch::StockKnifeCtrlZoom : eIPadNativePanDispatch::None;
}

static void wm_eventemulation(.text:
static void wm_eventemulation(wmEvent *event, bool test_only)
{
  /* Store last middle-mouse event value to make emulation work
   * when modifier keys are released first.
   * This really should be in a data structure somewhere. */

  /* Middle-mouse emulation. */
  if (U.flag & USER_TWOBUTTONMOUSE) {

    if (event->type == LEFTMOUSE) {
      const wmEventModifierFlag mod_test = (
#if !defined(WIN32)
          (U.mouse_emulate_3_button_modifier == USER_EMU_MMB_MOD_OSKEY) ? KM_OSKEY : KM_ALT
#else
          /* Disable for WIN32 for now because it accesses the start menu. */
          KM_ALT
#endif
      );

      if (event->val == KM_PRESS) {
        if (event->modifier & mod_test) {
          event->modifier &= ~mod_test;
          event->type = MIDDLEMOUSE;

          if (!test_only) {
            wm_eventemulation_mouse = MIDDLEMOUSE;
          }
        }
      }
      else if (event->val == KM_RELEASE) {
        /* Only send middle-mouse release if emulated. */
        if (wm_eventemulation_mouse == MIDDLEMOUSE) {
          event->type = MIDDLEMOUSE;
          event->modifier &= ~mod_test;
        }

        if (!test_only) {
          wm_eventemulation_mouse = EVENT_NONE;
        }
      }
    }
  }

  /* Numeric-pad emulation. */
  if (U.flag & USER_NONUMPAD) {
    switch (event->type) {
      case EVT_ZEROKEY:
        event->type = EVT_PAD0;
        break;
      case EVT_ONEKEY:
        event->type = EVT_PAD1;
        break;
      case EVT_TWOKEY:
        event->type = EVT_PAD2;
        break;
      case EVT_THREEKEY:
        event->type = EVT_PAD3;
        break;
      case EVT_FOURKEY:
        event->type = EVT_PAD4;
        break;
      case EVT_FIVEKEY:
        event->type = EVT_PAD5;
        break;
      case EVT_SIXKEY:
        event->type = EVT_PAD6;
        break;
      case EVT_SEVENKEY:
        event->type = EVT_PAD7;
        break;
      case EVT_EIGHTKEY:
        event->type = EVT_PAD8;
        break;
      case EVT_NINEKEY:
        event->type = EVT_PAD9;
        break;
      case EVT_MINUSKEY:
        event->type = EVT_PADMINUS;
        break;
      case EVT_EQUALKEY:
        event->type = EVT_PADPLUSKEY;
        break;
      case EVT_BACKSLASHKEY:
        event->type = EVT_PADSLASHKEY;
        break;
      default: {
        break;
      }
    }
  }
}

static wmEvent *wm_event_add_trackpad(.text:
static wmEvent *wm_event_add_trackpad(wmWindow *win, const wmEvent *event, int deltax, int deltay)
{
  bool all_physical_pencil_precision_pan =
      (event->flag & WM_EVENT_IS_PENCIL_PRECISION_PAN) != 0;
  /* Ignore in between trackpad events for performance, we only need high accuracy
   * for painting with mouse moves, for navigation using the accumulated value is ok. */
  const wmEvent *event_last = static_cast<wmEvent *>(win->runtime->event_queue.last);
  if (event_last && event_last->type == event->type &&
      (event_last->flag & WM_EVENT_IS_TOUCH_PINCH) == (event->flag & WM_EVENT_IS_TOUCH_PINCH))
  {
    deltax += event_last->xy[0] - event_last->prev_xy[0];
    deltay += event_last->xy[1] - event_last->prev_xy[1];
    all_physical_pencil_precision_pan &=
        (event_last->flag & WM_EVENT_IS_PENCIL_PRECISION_PAN) != 0;

    wm_event_free_last(win);
  }

  /* Set prev_xy, the delta is computed from this in operators. */
  wmEvent *event_new = wm_event_add_intern(win, event);
  event_new->prev_xy[0] = event_new->xy[0] - deltax;
  event_new->prev_xy[1] = event_new->xy[1] - deltay;
  /* Preserve native merging and deltas; mixed source aggregates keep fallback. */
  if (!all_physical_pencil_precision_pan) {
    event_new->flag &= ~WM_EVENT_IS_PENCIL_PRECISION_PAN;
  }

  return event_new;
}

struct EnumPropertyItem {.text:
struct EnumPropertyItem {
