      {KNF_MODAL_X_AXIS, "X_AXIS", 0, "X Axis Locking", ""},
      {KNF_MODAL_Y_AXIS, "Y_AXIS", 0, "Y Axis Locking", ""},
      {KNF_MODAL_Z_AXIS, "Z_AXIS", 0, "Z Axis Locking", ""},
      {0, nullptr, 0, nullptr, nullptr},
  };

  wmKeyMap *keymap = WM_modalkeymap_find(keyconf, "Knife Tool Modal Map");

  /* This function is called for each space-type, only needs to add map once. */
  if (keymap && keymap->modal_items) {
    return nullptr;
  }

  keymap = WM_modalkeymap_ensure(keyconf, "Knife Tool Modal Map", modal_items);

  WM_modalkeymap_assign(keymap, "MESH_OT_knife_tool");

  return keymap;
}

int RNA_enum_from_identifier(.text:
int RNA_enum_from_identifier(const EnumPropertyItem *item, const char *identifier)
{
  int i = 0;
  for (; item->identifier; item++, i++) {
    if (item->identifier[0] && STREQ(item->identifier, identifier)) {
      return i;
    }
  }
  return -1;
}

bool RNA_enum_value_from_id(.text:
bool RNA_enum_value_from_id(const EnumPropertyItem *item, const char *identifier, int *r_value)
{
  const int i = RNA_enum_from_identifier(item, identifier);
  if (i != -1) {
    *r_value = item[i].value;
    return true;
  }
  return false;
}

static wmKeyMapItem *rna_KeyMap_item_new.text:
static wmKeyMapItem *rna_KeyMap_item_new_modal(wmKeyMap *km,
                                               ReportList *reports,
                                               const char *propvalue_str,
                                               int type,
                                               int value,
                                               bool any,
                                               int shift,
                                               int ctrl,
                                               int alt,
                                               int oskey,
                                               int hyper,
                                               int keymodifier,
                                               int direction,
                                               bool repeat)
{
  /* only modal maps */
  if ((km->flag & KEYMAP_MODAL) == 0) {
    BKE_report(reports, RPT_ERROR, "Not a modal keymap");
    return nullptr;
  }

  wmKeyMapItem *kmi = nullptr;
  int propvalue = 0;

  KeyMapItem_Params params{};
  params.type = type;
  params.value = value;
  params.modifier = keymap_item_modifier_flag_from_args(any, shift, ctrl, alt, oskey, hyper);
  params.keymodifier = keymodifier;
  params.direction = direction;

  /* not initialized yet, do delayed lookup */
  if (!km->modal_items) {
    kmi = WM_modalkeymap_add_item_str(km, &params, propvalue_str);
  }
  else {
    if (RNA_enum_value_from_id(static_cast<const EnumPropertyItem *>(km->modal_items),
                               propvalue_str,
                               &propvalue) == 0)
    {
      BKE_report(reports, RPT_WARNING, "Property value not in enumeration");
    }
    kmi = WM_modalkeymap_add_item(km, &params, propvalue);
  }

  if (!repeat) {
    kmi->flag |= KMI_REPEAT_IGNORE;
  }

  return kmi;
}

wmKeyMap *WM_keymap_active(.text:
wmKeyMap *WM_keymap_active(const wmWindowManager *wm, wmKeyMap *keymap)
{
  if (!keymap) {
    return nullptr;
  }

  /* First user defined keymaps. */
  wmKeyMap *km = WM_keymap_list_find(
      &wm->runtime->userconf->keymaps, keymap->idname, keymap->spaceid, keymap->regionid);

  if (km) {
    return km;
  }

  return keymap;
}

struct wmEvent_ModalMapStore {.text:
struct wmEvent_ModalMapStore {
  wmEventType prev_type;
  short prev_val;

  bool dbl_click_disabled;
}

static wmKeyMapItem *wm_eventmatch_modal.text:
static wmKeyMapItem *wm_eventmatch_modal_keymap_items(const wmKeyMap *keymap,
                                                      wmOperator *op,
                                                      const wmEvent *event)
{
  LISTBASE_FOREACH (wmKeyMapItem *, kmi, &keymap->items) {
    /* Should already be handled by #wm_user_modal_keymap_set_items. */
    BLI_assert(kmi->propvalue_str[0] == '\0');
    if (wm_eventmatch(event, kmi)) {
      if ((keymap->poll_modal_item == nullptr) || keymap->poll_modal_item(op, kmi->propvalue)) {
        return kmi;
      }
    }
  }
  return nullptr;
}

static void wm_event_modalkeymap_begin(.text:
static void wm_event_modalkeymap_begin(const bContext *C,
                                       wmOperator *op,
                                       wmEvent *event,
                                       wmEvent_ModalMapStore *event_backup)
{
  BLI_assert(event->type != EVT_MODAL_MAP);

  /* Support for modal key-map in macros. */
  if (op->opm) {
    op = op->opm;
  }

  event_backup->dbl_click_disabled = false;

  if (op->type->modalkeymap) {
    wmKeyMap *keymap = WM_keymap_active(CTX_wm_manager(C), op->type->modalkeymap);
    wmKeyMapItem *kmi = nullptr;

    const wmEvent *event_match = nullptr;
    wmEvent event_no_dbl_click;

    if ((kmi = wm_eventmatch_modal_keymap_items(keymap, op, event))) {
      event_match = event;
    }
    else if (event->val == KM_DBL_CLICK) {
      event_no_dbl_click = *event;
      event_no_dbl_click.val = KM_PRESS;
      if ((kmi = wm_eventmatch_modal_keymap_items(keymap, op, &event_no_dbl_click))) {
        event_match = &event_no_dbl_click;
      }
    }

    if (event_match != nullptr) {
      event_backup->prev_type = event->prev_type;
      event_backup->prev_val = event->prev_val;

      event->prev_type = event_match->type;
      event->prev_val = event_match->val;
      event->type = EVT_MODAL_MAP;
      event->val = kmi->propvalue;

      /* Avoid double-click events even in the case of #EVT_MODAL_MAP,
       * since it's possible users configure double-click key-map items
       * which would break when modal functions expect press/release. */
      if (event->prev_val == KM_DBL_CLICK) {
        event->prev_val = KM_PRESS;
        event_backup->dbl_click_disabled = true;
      }
    }
  }

  if (event->type != EVT_MODAL_MAP) {
    /* This bypass just disables support for double-click in modal handlers. */
    if (event->val == KM_DBL_CLICK) {
      event->val = KM_PRESS;
      event_backup->dbl_click_disabled = true;
    }
  }
}

static void wm_event_modalkeymap_end(.text:
static void wm_event_modalkeymap_end(wmEvent *event, const wmEvent_ModalMapStore *event_backup)
{
  if (event->type == EVT_MODAL_MAP) {
    event->type = event->prev_type;
    event->val = event->prev_val;

    event->prev_type = event_backup->prev_type;
    event->prev_val = event_backup->prev_val;
  }

  if (event_backup->dbl_click_disabled) {
    event->val = KM_DBL_CLICK;
  }
}

static eHandlerActionFlag wm_handler_ope.text:
static eHandlerActionFlag wm_handler_operator_call(bContext *C,
                                                   ListBase *handlers,
                                                   wmEventHandler *handler_base,
                                                   wmEvent *event,
                                                   PointerRNA *properties,
                                                   const char *kmi_idname,
                                                   bool ipad_pencil_owner_teardown = false,
                                                   eIPadNativePanDispatch ipad_node_view2d =
                                                       eIPadNativePanDispatch::None)
{
  wmOperatorStatus retval = OPERATOR_PASS_THROUGH;
  bool ipad_knife_action = false;
  ScrArea *ipad_knife_area = nullptr;
  ARegion *ipad_knife_region = nullptr;
#ifdef WITH_APPLE_CROSSPLATFORM
  if (event && event->type == IPAD_KNIFE_ACTION) {
    wmEventHandler_Op *fresh_handler = nullptr;
    if (!wm_ipad_knife_request_resolve(C, CTX_wm_window(C), event, &fresh_handler,
                                       &ipad_knife_area, &ipad_knife_region) ||
        &fresh_handler->head != handler_base)
    {
      return WM_HANDLER_BREAK | WM_HANDLER_HANDLED;
    }
    ipad_knife_action = true;
  }
#endif

  /* Derived, modal or blocking operator. */
  if ((handler_base->type == WM_HANDLER_TYPE_OP) &&
      (((wmEventHandler_Op *)handler_base)->op != nullptr))
  {
    wmEventHandler_Op *handler = (wmEventHandler_Op *)handler_base;
    wmOperator *op = handler->op;
    wmOperatorType *ot = op->type;
    bool ipad_pencil_owner_teardown_admitted = false;
#ifdef WITH_APPLE_CROSSPLATFORM
    if (ipad_pencil_owner_teardown && handler->ipad_pencil_paint_serial && event &&
        event->type == EVENT_NONE)
    {
      ipad_pencil_owner_teardown_admitted =
          wm_ipad_pencil_paint_modal_admit(
              C, CTX_wm_window(C), event, handler, true) == eIPadPencilPaintModalAdmission::Cancel;
    }
#else
    UNUSED_VARS(ipad_pencil_owner_teardown);
#endif

    if (!wm_operator_check_locked_interface(C, ot) && !ipad_pencil_owner_teardown_admitted) {
      /* Interface is locked and operator is not allowed to run,
       * nothing to do in this case. */
    }
    else if (ot->modal) {
      /* We set context to where modal handler came from. */
      wmWindowManager *wm = CTX_wm_manager(C);
      wmWindow *win = CTX_wm_window(C);
      ScrArea *area = CTX_wm_area(C);
      ARegion *region = CTX_wm_region(C);

      if (ipad_knife_action) {
        CTX_wm_area_set(C, ipad_knife_area);
        CTX_wm_region_set(C, ipad_knife_region);
      }
      else if (!ipad_pencil_owner_teardown) {
        wm_handler_op_context(C, handler, event);
      }
      bool ipad_pencil_paint_interrupt = false;
#ifdef WITH_APPLE_CROSSPLATFORM
      if (handler->ipad_pencil_paint_serial || ipad_pencil_owner_teardown) {
        const eIPadPencilPaintModalAdmission admission =
            ipad_pencil_owner_teardown ?
                (ipad_pencil_owner_teardown_admitted ?
                     eIPadPencilPaintModalAdmission::Cancel :
                     eIPadPencilPaintModalAdmission::Consume) :
                wm_ipad_pencil_paint_modal_admit(C, win, event, handler);
        if (admission == eIPadPencilPaintModalAdmission::Consume ||
            (ipad_pencil_owner_teardown && admission != eIPadPencilPaintModalAdmission::Cancel))
        {
          CTX_wm_area_set(C, area);
          CTX_wm_region_set(C, region);
          return WM_HANDLER_BREAK | WM_HANDLER_HANDLED;
        }
        /* Cancel while the frozen owner is still live, before this other input can
         * switch context or reach the old modal operation. The ordinary WM status
         * path removes and frees the operator/handler exactly once. */
        ipad_pencil_paint_interrupt =
            admission == eIPadPencilPaintModalAdmission::Cancel ||
            (admission == eIPadPencilPaintModalAdmission::Dispatch && event &&
             (event->flag & WM_EVENT_IS_POINTER_CANCEL));
      }
#endif
      wmEvent_ModalMapStore event_backup;
      bool modalkeymap_started = false;
      const intptr_t undo_id_prev = wm_operator_undo_active_id(wm);
      const intptr_t register_id_prev = wm_operator_register_active_id(wm);
      if (ot->flag & OPTYPE_UNDO) {
        wm->op_undo_depth++;
      }

      if (ipad_pencil_paint_interrupt) {
#ifdef WITH_APPLE_CROSSPLATFORM
        if (handler->ipad_pencil_paint_serial) {
          wm_ipad_pencil_paint_cancelled_contact_mark(win, handler);
        }
#endif
        ot->cancel(C, op);
        retval = OPERATOR_CANCELLED | OPERATOR_PASS_THROUGH;
      }
      else if (ipad_knife_action) {
#ifdef WITH_APPLE_CROSSPLATFORM
        /* The helper constructs a clean native modal-map event. Do not run
         * modal-keymap translation on this private semantic request. */
        wm_region_mouse_co(C, event);
        const auto *request = static_cast<const wmIPadKnifeRequest *>(event->customdata);
        retval = ED_mesh_knife_modal_action(C, op, event,
                                            request->action == wmIPadKnifeAction::Confirm);
        OPERATOR_RETVAL_CHECK(retval);
#endif
      }
      else {
        wm_region_mouse_co(C, event);
        wm_event_modalkeymap_begin(C, op, event, &event_backup);
        modalkeymap_started = true;

        /* Warning, after this call all context data and event may be freed. see check below. */
        retval = ot->modal(C, op, event);
        OPERATOR_RETVAL_CHECK(retval);
      }

      if (ot->flag & OPTYPE_UNDO && CTX_wm_manager(C) == wm) {
        wm->op_undo_depth--;
      }

      /* When the window changes the modal modifier may have loaded a new blend file
       * (the `system_demo_mode` add-on does this), so we have to assume the event,
       * operator, area, region etc have all been freed. */
      if (CTX_wm_window(C) == win) {

        if (modalkeymap_started) {
          wm_event_modalkeymap_end(event, &event_backup);
        }

        if (retval & (OPERATOR_CANCELLED | OPERATOR_FINISHED)) {
          wm_operator_reports(C, op, retval, false);

          wmOperator *op_test = handler->op->opm ? handler->op->opm : handler->op;
          if (op_test->type->modalkeymap) {
            WM_window_status_area_tag_redraw(win);
          }
        }
        else {
          /* Not very common, but modal operators may report before finishing. */
          if (!BLI_listbase_is_empty(&op->reports->list)) {
            WM_event_add_notifier(C, NC_SPACE | ND_SPACE_INFO_REPORT, nullptr);
            WM_reports_from_reports_move(wm, op->reports);
          }
        }

        /* Important to run 'wm_operator_finished' before setting the context members to null. */
        if (retval & OPERATOR_FINISHED) {
          const bool has_undo_step = (undo_id_prev != wm_operator_undo_active_id(wm));
          const bool has_register = (register_id_prev != wm_operator_register_active_id(wm));

          wm_operator_finished(C, op, false, true, has_undo_step, has_register);
          handler->op = nullptr;
        }
        else if (retval & (OPERATOR_CANCELLED | OPERATOR_FINISHED)) {
          WM_operator_free(op);
          handler->op = nullptr;
        }

        /* Putting back screen context, `reval` can pass through after modal failures! */
        if ((retval & OPERATOR_PASS_THROUGH) || wm_event_always_pass(event)) {
          CTX_wm_area_set(C, area);
          CTX_wm_region_set(C, region);
        }
        else {
          /* This special cases is for areas and regions that get removed. */
          CTX_wm_area_set(C, nullptr);
          CTX_wm_region_set(C, nullptr);
        }

        /* Update gizmos during modal handlers. */
        wm_gizmomaps_handled_modal_update(C, event, handler);

        /* Remove modal handler, operator itself should have been canceled and freed. */
        if (retval & (OPERATOR_CANCELLED | OPERATOR_FINISHED)) {
          WM_cursor_grab_disable(CTX_wm_window(C), nullptr);

          BLI_remlink(handlers, handler);
          wm_event_free_handler(&handler->head);

          /* Prevent silly errors from operator users. */
          // retval &= ~OPERATOR_PASS_THROUGH;
        }
      }
    }
    else {
      CLOG_ERROR(WM_LOG_EVENTS, "Missing modal '%s'", op->idname);
    }
  }
  else {
    wmOperatorType *ot = WM_operatortype_find(kmi_idname, false);

    if (ot && wm_operator_check_locked_interface(C, ot)) {
#ifdef WITH_APPLE_CROSSPLATFORM
      /* If Apple Pencil is touching while Annotate or Grease Pencil tool is active,
       * disable 3D selection (left click) so Apple Pencil draws strokes cleanly. */
      if (event->tablet.active == EVT_TABLET_STYLUS &&
          (BLI_strcasestr(ot->idname, "select") != nullptr))
      {
        bToolRef *tref = WM_toolsystem_ref_from_context(C);
        if (tref && (BLI_strcasestr(tref->idname, "annotate") != nullptr ||
                     BLI_strcasestr(tref->idname, "gpencil") != nullptr))
        {
          /* In Annotate mode, route Pencil taps to annotation stroke instead of selecting objects */
          wmOperatorType *annot_ot = WM_operatortype_find("GPENCIL_OT_annotate", false);
          if (annot_ot) {
            WM_operator_name_call(C, "GPENCIL_OT_annotate", blender::wm::OpCallContext::InvokeDefault, nullptr, event);
          }
          return WM_HANDLER_BREAK;
        }
      }
#endif
      bool use_last_properties = true;
      PointerRNA tool_properties = {};

      bToolRef *keymap_tool = nullptr;
      if (handler_base->type == WM_HANDLER_TYPE_KEYMAP) {
        keymap_tool = ((wmEventHandler_Keymap *)handler_base)->keymap_tool;
      }
      else if (handler_base->type == WM_HANDLER_TYPE_GIZMO) {
        wmGizmoMap *gizmo_map = ((wmEventHandler_Gizmo *)handler_base)->gizmo_map;
        wmGizmo *gz = wm_gizmomap_highlight_get(gizmo_map);
        if (gz && (gz->flag & WM_GIZMO_OPERATOR_TOOL_INIT)) {
          keymap_tool = WM_toolsystem_ref_from_context(C);
        }
      }

      const bool is_tool = (keymap_tool != nullptr);
      const bool use_tool_properties = is_tool;

      if (use_tool_properties) {
        WM_toolsystem_ref_properties_init_for_keymap(
            keymap_tool, &tool_properties, properties, ot);
#ifdef WITH_APPLE_CROSSPLATFORM
        /* Fine gain is deliberate tool state for canvas and gizmo drags.
         * Native gizmos still own their basis, including the view-facing rotation ring. */
        WM_toolsystem_ref_properties_for_transform(C, keymap_tool, &tool_properties, ot,
                                                  handler_base->type == WM_HANDLER_TYPE_KEYMAP);
#endif
        properties = &tool_properties;
        use_last_properties = false;
      }

      retval = wm_operator_invoke(
          C, ot, event, properties, nullptr, false, use_last_properties, ipad_node_view2d);

      if (use_tool_properties) {
        WM_operator_properties_free(&tool_properties);
      }

      /* Link gizmo if #WM_GIZMOGROUPTYPE_TOOL_INIT is set. */
      if (retval & OPERATOR_FINISHED) {
        if (is_tool) {
          bToolRef_Runtime *tref_rt = keymap_tool->runtime;
          if (tref_rt->gizmo_group[0]) {
            const char *idname = tref_rt->gizmo_group;
            wmGizmoGroupType *gzgt = WM_gizmogrouptype_find(idname, false);
            if (gzgt != nullptr) {
              if ((gzgt->flag & WM_GIZMOGROUPTYPE_TOOL_INIT) != 0) {
                ARegion *region = CTX_wm_region(C);
                if (region != nullptr) {
                  wmGizmoMapType *gzmap_type = WM_gizmomaptype_ensure(&gzgt->gzmap_params);
                  WM_gizmo_group_type_ensure_ptr_ex(gzgt, gzmap_type);
                  wmGizmoGroup *gzgroup = WM_gizmomaptype_group_init_runtime_with_region(
                      gzmap_type, gzgt, region);
                  /* We can't rely on drawing to initialize gizmo's since disabling
                   * overlays/gizmos will prevent pre-drawing setup calls, see #60905. */
                  WM_gizmogroup_ensure_init(C, gzgroup);
                }
              }
            }
          }
        }
      }
      /* Done linking gizmo. */
    }
  }

  /* Finished and pass through flag as handled. */
  if (retval == (OPERATOR_FINISHED | OPERATOR_PASS_THROUGH)) {
    return WM_HANDLER_HANDLED;
  }

  /* Modal unhandled, break. */
  if (retval == (OPERATOR_PASS_THROUGH | OPERATOR_RUNNING_MODAL)) {
    return (WM_HANDLER_BREAK | WM_HANDLER_MODAL);
  }

  if (retval & OPERATOR_PASS_THROUGH) {
    return WM_HANDLER_CONTINUE;
  }

  return WM_HANDLER_BREAK;
}

static wmOperatorStatus wm_operator_invo.text:
static wmOperatorStatus wm_operator_invoke(bContext *C,
                                           wmOperatorType *ot,
                                           const wmEvent *event,
                                           PointerRNA *properties,
                                           ReportList *reports,
                                           const bool poll_only,
                                           bool use_last_properties,
                                           [[maybe_unused]] eIPadNativePanDispatch ipad_node_view2d =
                                               eIPadNativePanDispatch::None)
{
  wmOperatorStatus retval = OPERATOR_PASS_THROUGH;

  /* This is done because complicated setup is done to call this function
   * that is better not duplicated. */
  if (poll_only) {
    return wmOperatorStatus(WM_operator_poll(C, ot));
  }

#ifdef WITH_APPLE_CROSSPLATFORM
  if (!wm_ipad_native_pan_denial_profile(C, event, ot, ipad_node_view2d))
  {
    ipad_node_view2d = eIPadNativePanDispatch::None;
  }
#endif
  if (WM_operator_poll(C, ot)) {
#ifdef WITH_APPLE_CROSSPLATFORM
    if (wm_ipad_native_pan_denial_profile(C, event, ot, ipad_node_view2d))
    {
      /* No operator or native navigation state has been allocated. This consumed
       * default navigation attempt needs no cancel/free callback. */
      return OPERATOR_CANCELLED;
    }
#endif
    wmWindowManager *wm = CTX_wm_manager(C);
    const intptr_t undo_id_prev = wm_operator_undo_active_id(wm);
    const intptr_t register_id_prev = wm_operator_register_active_id(wm);

    /* If `reports == nullptr`, they'll be initialized. */
    wmOperator *op = wm_operator_create(wm, ot, properties, reports);

    CLOG_AT_LEVEL(WM_LOG_OPERATORS,
                  /* Avoid logging very noisy hover/timer driven operators at info level. */
                  ((op->type->flag & OPTYPE_REGISTER) ? CLG_LEVEL_INFO : CLG_LEVEL_DEBUG),
                  "Started %s",
                  WM_operator_pystring(C, op, false, true).c_str());

    const bool is_nested_call = (wm->op_undo_depth != 0);

    if (event != nullptr) {
      op->flag |= OP_IS_INVOKE;
    }

    /* Initialize setting from previous run. */
    if (!is_nested_call && use_last_properties) { /* Not called by a Python script. */
      WM_operator_last_properties_init(op);
    }

    if ((event == nullptr) || (event->type != MOUSEMOVE)) {
      CLOG_DEBUG(WM_LOG_EVENTS,
                 "Handle event %d win %p op %s",
                 event ? event->type : 0,
                 CTX_wm_screen(C)->active_region,
                 ot->idname);
    }

    if (op->type->invoke && event) {
      /* Make a copy of the event as it's `const` and the #wmEvent.mval to be written into. */
      wmEvent event_temp = *event;
      wm_region_mouse_co(C, &event_temp);

      if (op->type->flag & OPTYPE_UNDO) {
        wm->op_undo_depth++;
      }

      retval = op->type->invoke(C, op, &event_temp);
      OPERATOR_RETVAL_CHECK(retval);

      if (op->type->flag & OPTYPE_UNDO && CTX_wm_manager(C) == wm) {
        wm->op_undo_depth--;
      }
    }
    else if (op->type->exec) {
      if (op->type->flag & OPTYPE_UNDO) {
        wm->op_undo_depth++;
      }

      retval = op->type->exec(C, op);
      OPERATOR_RETVAL_CHECK(retval);

      if (op->type->flag & OPTYPE_UNDO && CTX_wm_manager(C) == wm) {
        wm->op_undo_depth--;
      }
    }
    else {
      /* Debug, important to leave a while, should never happen. */
      CLOG_ERROR(WM_LOG_OPERATORS, "Invalid operator call '%s'", op->idname);
    }

    /* NOTE: if the report is given as an argument then assume the caller will deal with displaying
     * them currently Python only uses this. */
    if (!(retval & OPERATOR_HANDLED) && (retval & (OPERATOR_FINISHED | OPERATOR_CANCELLED))) {
      /* Only show the report if the report list was not given in the function. */
      wm_operator_reports(C, op, retval, (reports != nullptr));
    }

    if (retval & OPERATOR_HANDLED) {
      /* Do nothing, #wm_operator_exec() has been called somewhere. */
    }
    else if (retval & OPERATOR_FINISHED) {
      const bool has_undo_step = (undo_id_prev != wm_operator_undo_active_id(wm));
      const bool has_register = (register_id_prev != wm_operator_register_active_id(wm));
      const bool store = !is_nested_call && use_last_properties;
      wm_operator_finished(C, op, false, store, has_undo_step, has_register);
    }
    else if (retval & OPERATOR_RUNNING_MODAL) {
      /* Take ownership of reports (in case python provided its own). */
      op->reports->flag |= RPT_FREE;

      /* Grab cursor during blocking modal operators (X11)
       * Also check for macro. */
      if (ot->flag & OPTYPE_BLOCKING || (op->opm && op->opm->type->flag & OPTYPE_BLOCKING)) {
        eWM_CursorWrapAxis wrap = WM_CURSOR_WRAP_NONE;
        const rcti *wrap_region = nullptr;

        if (event && (U.uiflag & USER_CONTINUOUS_MOUSE)) {
          const wmOperator *op_test = op->opm ? op->opm : op;
          const wmOperatorType *ot_test = op_test->type;
          if ((ot_test->flag & OPTYPE_GRAB_CURSOR_XY) || (op_test->flag & OP_IS_MODAL_GRAB_CURSOR))
          {
            wrap = WM_CURSOR_WRAP_XY;
          }
          else if (ot_test->flag & OPTYPE_GRAB_CURSOR_X) {
            wrap = WM_CURSOR_WRAP_X;
          }
          else if (ot_test->flag & OPTYPE_GRAB_CURSOR_Y) {
            wrap = WM_CURSOR_WRAP_Y;
          }
        }

        if (wrap) {
          ARegion *region = CTX_wm_region(C);
          ScrArea *area = CTX_wm_area(C);

          /* Wrap only in X for header. */
          if (region && RGN_TYPE_IS_HEADER_ANY(region->regiontype)) {
            wrap = WM_CURSOR_WRAP_X;
          }

          if (region && region->regiontype == RGN_TYPE_WINDOW &&
              BLI_rcti_isect_pt_v(&region->winrct, event->xy))
          {
            wrap_region = &region->winrct;
          }
          else if (area && BLI_rcti_isect_pt_v(&area->totrct, event->xy)) {
            wrap_region = &area->totrct;
          }
        }

        WM_cursor_grab_enable(CTX_wm_window(C), wrap, wrap_region, false);
      }

      /* Cancel UI handlers, typically tool-tips that can hang around
       * while dragging the view or worse, that stay there permanently
       * after the modal operator has swallowed all events and passed
       * none to the UI handler. */
      wm_event_handler_ui_cancel(C);
    }
    else {
      WM_operator_free(op);
    }
  }

  return retval;
}
